import { createMainPatternView } from './main-pattern-view.js';
import { deviceSettingsData as serializeDeviceSettings } from './device-configuration.js';
import { createRecognitionPanel } from './recognition-panel-view.js';
import { createFeatureLayerPanel } from './feature-layer-panel-view.js';
import { featureLayerGroups, featuresInView } from './feature-layers.js';
import { parsePlan, serializePlan, planFromState, stateFromPlan, planHash } from './plan-format.js';
import { loadStoredPlan, storePlan } from './plan-store.js';
import { selectionHref, APP_PAGES } from './application-selection.js';
export function createMainPage({workbenchHref='./geometry-preview.html',datasetId,datasetVersion,features,recognitionItems,state,sceneView,projectionView,createController,scenarioId=null,releases=[],candidateIds=[],capabilities,environmentDescription,backendLabel,root=document,storage=localStorage}){
 const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)];

 const projection={mode:'counts',data:null,recognition:null,precision:false};
 const precisionKey=`muon-precision:${datasetId}`;try{projection.precision=storage.getItem(precisionKey)==='1';}catch{}
 // Plan (PLAN_FORMAT.md): stations, poses, detector and selection persist as one versioned plan per release.
 let planTitle='',selected=[];
 const mainPatterns=createMainPatternView({canvas:$('#projectionCanvas'),host:$('#projectionBody'),backendLabel});
 const recognition=createRecognitionPanel({root,features,items:recognitionItems,storage,storageKey:`muon-recognition:${datasetId}`,onChange:()=>{projection.recognition=recognition.state();drawProjection();},onHoverItem:item=>sceneView.emphasiseFeatures(item?.kind==='features'?[...item.featureIds]:[])});
 const layerFeatureIds=featureLayerGroups(features).flatMap(group=>group.featureIds);
 const featureLayers=createFeatureLayerPanel({root,features,storage,storageKey:`muon-feature-layers:${datasetId}`,onVisibility:(id,visible)=>sceneView.setFeatureVisible(id,visible),onHoverFeatures:ids=>sceneView.emphasiseFeatures(ids)});projection.recognition=recognition.state();
 // Each input carries the plan it came from (provenance, not identity): plan hash + active station id.
 const inputs=()=>({...state.snapshot(),plan:{hash:planHash(currentPlan()),stationId:state.candidates[state.active].id}});
 const controller=createController({readInputs:inputs,onInvalidate(){mainPatterns.invalidate();projection.data=null;sceneView.setCoverageResult(null);sceneView.setFeaturesInView(null);recognition.update(null);projection.recognition=recognition.state();$('#projectionReadout').textContent='姿态更新中…';},onStart(input){sceneView.drawDetector(input.station,input.device);},onQuick({cloud,metrics},input){if(cloud)sceneView.showFlux(cloud,input.station);if(metrics){showQuickMetrics(metrics);sceneView.showRay(metrics.center,input.station,metrics.dirDoc);}},onProgress({quality,progress}){$('#projectionReadout').textContent=`${quality==='preview'?'快速预览':'精细投影'}计算中… ${Math.round(100*progress)}%`;},onResult(data,input){projection.data=data;sceneView.setCoverageResult(data,input.device);sceneView.setFeaturesInView(featuresInView(data,layerFeatureIds,{threshold:recognition.state().threshold}));recognition.update(data);projection.recognition=recognition.state();if(data.quality==='final'){updateProjectionAssessment(data,input.station);if(!capabilities.fluxCloud){const mid=Math.floor(data.n/2),pixel=data.values[mid*data.n+mid];sceneView.showRay(pixel.q,input.station,pixel.dir);}mainPatterns.update(data.patternResult,projection.mode);}drawProjection();},onError(error){console.error(error);$('#projectionReadout').textContent='评估计算失败：'+error.message;}});
 const scheduleDetectorUpdate=()=>controller.schedule(),resize=()=>sceneView.resize(),setView=mode=>sceneView.setView(mode),drawFluxCloud=()=>sceneView.drawFluxCloud();
 const drawProjection=()=>projectionView.draw(projection,state.response);
 const applyDeviceSettings=s=>state.configure(s);
 const deviceSettingsData=()=>serializeDeviceSettings(state.configuration);
 $('#fluxMode')?.addEventListener('change',drawFluxCloud);
 $('#projectionToggle')?.addEventListener('click',()=>{const b=$('#projectionBody'),hidden=b.style.display==='none';b.style.display=hidden?'block':'none';$('#projectionToggle').textContent=hidden?'−':'+'});
$$('[data-projection]').forEach(b=>b.addEventListener('click',()=>{if(b.disabled)return;projection.mode=b.dataset.projection;$$('[data-projection]').forEach(x=>x.classList.toggle('active',x===b));mainPatterns.redraw(projection.mode);drawProjection()}));

function constrainProjectionPanel(){const panel=$('#projectionPanel'),viewport=$('#viewport');if(!panel||!viewport||!panel.style.left)return;const maxX=Math.max(0,viewport.clientWidth-panel.offsetWidth),maxY=Math.max(0,viewport.clientHeight-panel.offsetHeight),xRatio=Number(panel.dataset.xRatio),yRatio=Number(panel.dataset.yRatio),x=Number.isFinite(xRatio)?maxX*xRatio:parseFloat(panel.style.left)||0,y=Number.isFinite(yRatio)?maxY*yRatio:parseFloat(panel.style.top)||0;panel.style.left=Math.max(0,Math.min(maxX,x))+'px';panel.style.top=Math.max(0,Math.min(maxY,y))+'px'}
function makeProjectionDraggable(){const panel=$('#projectionPanel'),handle=$('#projectionHandle'),viewport=$('#viewport');let drag=null;handle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const p=panel.getBoundingClientRect(),v=viewport.getBoundingClientRect();drag={dx:e.clientX-p.left,dy:e.clientY-p.top,v};panel.style.right='auto';handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!drag)return;const maxX=Math.max(0,drag.v.width-panel.offsetWidth),maxY=Math.max(0,drag.v.height-panel.offsetHeight),x=Math.max(0,Math.min(maxX,e.clientX-drag.v.left-drag.dx)),y=Math.max(0,Math.min(maxY,e.clientY-drag.v.top-drag.dy));panel.style.left=x+'px';panel.style.top=y+'px';panel.dataset.xRatio=maxX?String(x/maxX):'0';panel.dataset.yRatio=maxY?String(y/maxY):'0'});handle.addEventListener('pointerup',e=>{drag=null;handle.releasePointerCapture(e.pointerId)});handle.addEventListener('pointercancel',()=>drag=null)}
 function updateProjectionAssessment(d,c){if(!d||d.quality!=='final')return;const mid=Math.floor(d.n/2),center=d.values[mid*d.n+mid],paths=d.values.filter(v=>v.factor>0).map(v=>v.q.totals.concrete),viewTransmission=100*d.weightedTransmission;$('#path').textContent=center.q.totals.concrete.toFixed(1)+' m';$('#opacity').textContent=center.q.mwe.toFixed(0);$('#count').textContent=d.total>999999?(d.total/1e6).toFixed(2)+'M':d.total>999?(d.total/1000).toFixed(1)+'k':Math.round(d.total);$('#sky').textContent=viewTransmission.toFixed(2)+'%';$('#rayCells').textContent=(center.q.cells?.length??center.q.segments?.length??0)+' 个';$('#rayRange').textContent=Math.min(...paths).toFixed(0)+'–'+Math.max(...paths).toFixed(0)+' m'}
 function showQuickMetrics({center,count,weightedTransmission,paths}){$('#path').textContent=center.totals.concrete.toFixed(1)+' m';$('#opacity').textContent=center.mwe.toFixed(0);$('#count').textContent=count>999?(count/1000).toFixed(1)+'k':count;$('#sky').textContent=(100*weightedTransmission).toFixed(1)+'%';$('#rayCells').textContent=center.cells.length+' 个';$('#rayRange').textContent=Math.min(...paths).toFixed(0)+'–'+Math.max(...paths).toFixed(0)+' m';}
 function renderList(){const h=$('#candidateList');h.innerHTML='';state.candidates.forEach((c,i)=>{const d=document.createElement('div');d.className='candidate'+(i===state.active?' active':'');d.innerHTML=`<b>${c.name}</b><span>X ${c.x.toFixed(1)} · Y ${c.y.toFixed(1)} · Z ${c.z.toFixed(1)}</span>`;d.onclick=()=>{state.select(i);persistPlan();sync();renderList();scheduleDetectorUpdate()};h.append(d)})}
 function syncDeviceStatus(){const pct=v=>(100*v).toFixed(1).replace(/\.0$/,'')+'%',slope=v=>v.toFixed(2);$('#areaOut').textContent=`${(state.device.width*1000).toFixed(1)} × ${(state.device.height*1000).toFixed(1)} mm`;$('#pitchOut').textContent=(state.device.stripPitch*1000).toFixed(2).replace(/0$/,'')+' mm';$('#stripsOut').textContent=state.device.stripsX;$('#spacingOut').textContent=state.device.spacing.toFixed(2)+' m';$('#baselineOut').textContent=state.device.baseline.toFixed(2)+' m';$('#fovOut').textContent=state.device.fovH.toFixed(1)+'° / '+state.device.fovV.toFixed(1)+'°';$('#coreFovOut').textContent=`${2*state.device.stripsX-1} × ${2*state.device.stripsY-1}`;$('#efficiencyOut').textContent=pct(state.response.layerEfficiency);$('#coincidenceOut').textContent=pct(state.response.layerEfficiency**state.device.layers*state.response.deadLiveFraction);$('#deadOut').textContent=pct(1-state.response.deadLiveFraction);$('#resolutionOut').textContent=state.response.angularResolutionDeg.toFixed(2).replace(/0$/,'')+'°';$('#exposureLabel').textContent=state.response.exposureDays+'天预计计数';$('#sxMin').textContent='−'+slope(state.device.maxSlopeX);$('#sxMax').textContent='+'+slope(state.device.maxSlopeX);$('#syMin').textContent='−'+slope(state.device.maxSlopeY);$('#syMax').textContent='+'+slope(state.device.maxSlopeY)}
 function sync(){const c=state.candidates[state.active];for(const k of ['name','x','y','z','az','el'])$('#'+k).value=c[k];$('#azNumber').value=c.az;$('#elNumber').value=c.el;syncDeviceStatus()}
 function currentPlan(){return planFromState({title:planTitle,release:datasetId,scenario:scenarioId,model:state.configuration.device.model,stations:state.candidates,activeIndex:state.active,selected:selected.filter(id=>state.candidates.some(c=>c.id===id)),settings:deviceSettingsData()});}
 function applyPlan(plan){const next=stateFromPlan(plan);planTitle=plan.title;selected=next.selected;state.replaceStations(next.stations);state.select(next.activeIndex);applyDeviceSettings(next.settings);}
 const persistPlan=()=>storePlan(storage,currentPlan());
 function download(text,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
 function fillDeviceForm(){const s=deviceSettingsData();$('#cfgWidth').value=(s.width*1000).toFixed(1);$('#cfgHeight').value=(s.height*1000).toFixed(1);$('#cfgPitch').value=(s.stripPitch*1000).toFixed(2);$('#cfgStrips').value=s.strips;$('#cfgSpacing').value=s.spacing;$('#cfgEfficiency').value=(s.layerEfficiency*100).toFixed(1);$('#cfgDead').value=((1-s.deadLiveFraction)*100).toFixed(1);$('#cfgResolution').value=s.angularResolutionDeg;$('#cfgSystematic').value=(s.systematicFraction*100).toFixed(1);$('#cfgExposure').value=s.exposureDays;$('#cfgAngular').value=s.angularModel}
 function bindDeviceSettings(){const dialog=$('#deviceDialog');$('#deviceSettings').onclick=()=>{fillDeviceForm();dialog.showModal()};$('#deviceClose').onclick=$('#deviceCancel').onclick=()=>dialog.close();$('#deviceForm').onsubmit=e=>{e.preventDefault();applyDeviceSettings({width:+$('#cfgWidth').value/1000,height:+$('#cfgHeight').value/1000,stripPitch:+$('#cfgPitch').value/1000,strips:+$('#cfgStrips').value,spacing:+$('#cfgSpacing').value,layerEfficiency:+$('#cfgEfficiency').value/100,deadLiveFraction:1-+$('#cfgDead').value/100,angularResolutionDeg:+$('#cfgResolution').value,systematicFraction:+$('#cfgSystematic').value/100,exposureDays:+$('#cfgExposure').value,angularModel:$('#cfgAngular').value});controller.clearCaches();persistPlan();syncDeviceStatus();dialog.close();scheduleDetectorUpdate()};dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}
 function updateWater(){if(!capabilities.continuousWater)return;const level=+$('#upLevel').value;$('#upOut').textContent='▽'+level+' m';state.setEnvironment({upstream:level});sceneView.setWater(level);scheduleDetectorUpdate();}
 function relocateFluxControl(){const select=$('#fluxMode'),legend=$('#fluxLegend');if(!select||!legend)return;const field=select.closest('.field'),wrap=document.createElement('label');wrap.className='flux-control';wrap.innerHTML='<span>热云显示量</span>';wrap.append(select);legend.prepend(wrap);field?.remove()}
 function setDamOpacity(){const opacity=+$('#damOpacity').value/100;$('#damOpacityOut').textContent=Math.round(opacity*100)+'%';sceneView.setDamOpacity(opacity);}
 // Importing a plan of another release or scenario stores it and opens that selection (it is loaded there on start).
 async function importPlan(event){const file=event.target.files[0];event.target.value='';if(!file)return;
  try{if(file.size>5*1024*1024)throw new Error('文件超过 5 MB');const plan=parsePlan(await file.text());
   if(plan.scene.contentHash!==null)throw new Error('用户加载的数据集尚不支持');if(!releases.includes(plan.scene.release))throw new Error(`未登记的数据集版本 ${plan.scene.release}`);
   if(plan.scene.release===datasetId&&(plan.scene.scenario??scenarioId)===scenarioId){applyPlan(plan);persistPlan();renderList();sync();scheduleDetectorUpdate();return;}
   storePlan(storage,plan);location.assign(selectionHref(APP_PAGES.main,{datasetId:plan.scene.release,scenarioId:plan.scene.scenario}));
  }catch(error){alert('方案导入失败：'+error.message);}}
 // Coverage highlight (FR-M10): view state, remembered per release; never changes results.
 function bindCoverage(){const key=`muon-coverage:${datasetId}`;let saved={};try{saved=JSON.parse(storage.getItem(key))??{};}catch{}
  const mode=$('#coverageMode'),core=$('#coverageCore'),context=$('#coverageContext');mode.value=['off','geometric','physical'].includes(saved.mode)?saved.mode:'off';core.checked=saved.core===true;context.checked=saved.context===true;
  const apply=()=>{const value={mode:mode.value,core:core.checked,context:context.checked};$('#coverageOptions').hidden=value.mode==='off';sceneView.setCoverage(value);try{storage.setItem(key,JSON.stringify(value));}catch{}};
  for(const input of [mode,core,context])input.onchange=apply;apply();}
 function bind(){document.querySelectorAll('.section-toggle').forEach(button=>button.onclick=()=>{const section=button.closest('.collapsible-section'),collapsed=section.classList.toggle('collapsed');button.textContent=collapsed?'▸':'▾';button.setAttribute('aria-expanded',String(!collapsed));button.title=(collapsed?'展开':'收起')+section.querySelector('h2').childNodes[0].textContent.trim()});const persist=persistPlan,updateField=(k,value)=>{state.updateStation(k,value);persist();sync();renderList();scheduleDetectorUpdate()};for(const k of ['name','x','y','z','az','el'])$('#'+k).addEventListener('input',e=>updateField(k,e.target.value));$('#azNumber').addEventListener('input',e=>updateField('az',e.target.value));$('#elNumber').addEventListener('input',e=>updateField('el',e.target.value));const toggleSidebar=side=>{const app=$('.app'),collapsed=app.classList.toggle(side+'-collapsed'),button=$(side==='left'?'#toggleLeft':'#toggleRight'),action=(collapsed?'展开':'收起')+(side==='left'?'左侧栏':'右侧栏');button.textContent=(collapsed?'显示':'收起')+(side==='left'?'左栏':'右栏');button.setAttribute('aria-label',action);button.title=action;requestAnimationFrame(resize)};$('#toggleLeft').onclick=()=>toggleSidebar('left');$('#toggleRight').onclick=()=>toggleSidebar('right');$('#viewSelect').onchange=e=>setView(e.target.value);$$('[data-layer]').forEach(e=>{sceneView.setLayer(e.dataset.layer,e.checked);e.onchange=()=>{sceneView.setLayer(e.dataset.layer,e.checked);if(e.dataset.layer==='flux')$('#fluxLegend').style.display=e.checked?'block':'none'}});$('#damOpacity').oninput=setDamOpacity;setDamOpacity();$('#upLevel').oninput=updateWater;$('#gridSize').disabled=true;$('#gridSize').closest('.field').style.display='none';$('#add').onclick=()=>{state.addStation();persist();sync();renderList();scheduleDetectorUpdate()};$('#remove').onclick=()=>{if(state.candidates.length<2)return;state.removeStation();persist();sync();renderList();scheduleDetectorUpdate()};$('#export').onclick=()=>download(serializePlan(currentPlan()),`muography-plan-${datasetId.replace(/[^A-Za-z0-9._-]+/g,'_')}.json`);$('#importPlan').onclick=()=>$('#importPlanFile').click();$('#importPlanFile').onchange=importPlan;window.addEventListener('resize',resize)}
 function configureCapabilities(){
  const continuous=capabilities.continuousWater;$('#upLevel').disabled=!continuous;$('#upLevel').title=continuous?'连续上游水位':'由已发布冻结工况决定，不支持连续水位';
  const significance=$('[data-projection="significance"]');significance.disabled=!capabilities.targetSignificance;significance.title=significance.disabled?'聚合材料尚无源实体归属；显著度未实现':'';
  $$('[data-layer]').forEach(input=>{input.disabled=!capabilities.layers.includes(input.dataset.layer);if(input.disabled)input.checked=false;});
  $('#fluxMode').disabled=!capabilities.fluxCloud;if(!capabilities.fluxCloud){$('#fluxLegend').hidden=true;$('#rayCells').nextElementSibling.textContent='中心线材料区段';}
  if(!continuous){const note=root.createElement('p');note.className='hint';note.id='backendLimitations';note.textContent='冻结网格工况：'+environmentDescription+'。连续水位、结构显著度和 legacy 热云未提供；范围外材料仍未知。';$('#environmentSection').append(note);}
 }
 return Object.freeze({start(){$('#specVersion').textContent=datasetVersion;configureCapabilities();if(capabilities.continuousWater){$('#upLevel').value=state.environment.upstream;$('#upOut').textContent='▽'+$('#upLevel').value+' m';}else $('#upOut').textContent='冻结工况';relocateFluxControl();const loaded=loadStoredPlan({storage,release:datasetId,scenario:scenarioId,model:state.configuration.device.model,candidateIds,defaultStations:state.candidates,defaultSettings:deviceSettingsData()});applyPlan(loaded.plan);if(loaded.warning)console.warn(loaded.warning);renderList();sync();for(const link of [$('#workbenchLink'),$('#workbenchLinkDiagnostics')])if(link)link.href=workbenchHref;sceneView.build();featureLayers.apply();bindCoverage();$('#precisionContours').checked=projection.precision;$('#precisionContours').onchange=e=>{projection.precision=e.target.checked;try{storage.setItem(precisionKey,projection.precision?'1':'0');}catch{}drawProjection();};bind();bindDeviceSettings();makeProjectionDraggable();controller.run();},constrainProjectionPanel,hoverFeature(id){sceneView.emphasiseFeatures(id?[id]:[]);projectionView.emphasiseItem(id?recognition.itemForFeature(id)?.id??null:null);},pickFeature(id){recognition.toggleFeature(id);},pickCoverage(ix,iy){projectionView.selectPixel(ix,iy);},dispose(){controller.dispose();mainPatterns.dispose?.();projectionView.dispose();sceneView.dispose();}});
}
